import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { DatabaseSync } from 'node:sqlite'

const app=readFileSync('src/App.tsx','utf8')
const table=readFileSync('src/features/sections/OrdersTableSection.tsx','utf8')
const worker=readFileSync('worker/domains/orders-write.ts','utf8')
assert(app.includes('async function correctOrderMetadata('),'Dedicated metadata UI API missing')
const begin=app.indexOf('async function correctOrderMetadata(')
const stop=app.indexOf('async function correctRecordedOrderItemPrice(',begin)
const frontend=app.slice(begin,stop)
assert(frontend.includes('metadataCorrection:{expected,next,expectedState}'),'Metadata must carry previous details and original financial/lifecycle snapshot')
assert(frontend.includes("method:'PATCH'")&&frontend.includes('prepareCriticalRequest(criticalKey,payload)'),'Metadata action must use idempotent critical PATCH')
assert(!frontend.includes('itemPriceCorrections:')&&!frontend.includes('payments:')&&!frontend.includes('items:')&&!frontend.includes('sourceType:'),'Metadata PATCH cannot include money or inventory')
assert((app.match(/correctOrderMetadata, correctRecordedOrderItemPrice/g)||[]).length===2,'Both normal and Kaspi UIs need metadata action')
assert(table.includes('Исправить реквизиты')&&table.includes('aria-label="Исправить реквизиты заказа"'),'One compact metadata form missing')
assert(table.includes('showRetiredExchangePriceActions=false'),'Niche old-V2 price correction must be hidden from routine UI')
assert(table.includes("maxWidth:'100%',minWidth:0,boxSizing:'border-box'"),'Price input must stay inside flexible row')
assert(table.includes("type={key==='orderDate'?'date':'text'}"),'Metadata date must be selectable')
assert(table.includes("key==='orderDate'&&!isAdmin"),'Only admin can backdate a sale')
assert(worker.includes("field==='requestId'||field==='metadataCorrection'"),'Metadata must be a narrow payload')
assert(worker.includes("if(isolatedMetadataRequest && rawMetadata)"),'Original field CAS missing')
assert(worker.includes('rawMetadata.expectedState')&&worker.includes('expected.receivedAmount'),'Original financial snapshot guard missing')
assert(worker.includes('SET order_date=?,customer_id=?,city=?,delivery_type=?,comment=?,updated_at=?'),'Only allowlisted metadata columns may be changed')
assert(worker.includes("!recordedPriceOnlyRequest && !isolatedMetadataRequest"),'Active exchanges must not block independent metadata')
assert(worker.includes("!recordedPriceOnlyRequest && !isolatedMetadataRequest)))"),'Shipment must not cause a product-rewrite on pure metadata')
assert(worker.includes("if (isolatedMetadataRequest) {"),'Metadata correction must preserve historical money totals')
assert(worker.includes("totalAmount:toInt(existingAny.total_amount,0)"),'Metadata must not recalculate order totals')
assert(worker.includes("else if(p.isolatedMetadataRequest && p.metadataBefore)"),'Atomic metadata preflight is mandatory')
assert(worker.includes("await db.batch([")&&worker.includes("ORDER_METADATA_STALE"),'Atomic compare-and-swap missing')
assert(worker.includes("if (p.rewriteItems || p.rewritePayments)"),'Stock/payment rewrites remain separate operations')

// Execute the exact SQL guard from the live worker against a synthetic order.
// Change in either money or shipping must block the write within one D1 batch.
const match=worker.match(/db\.prepare\(\`(SELECT json\('ORDER_METADATA_STALE'\)[\s\S]*?)\`\)\.bind\(id,m\.orderDate/)
assert(match,'Cannot extract current real metadata stale guard SQL')
const sql=new DatabaseSync(':memory:')
sql.exec("CREATE TABLE orders(id INTEGER PRIMARY KEY,order_date TEXT,customer_id INTEGER,city TEXT,delivery_type TEXT,comment TEXT,total_amount INTEGER,received_amount INTEGER,debt_amount INTEGER,return_amount INTEGER,shipping_status TEXT,order_status TEXT)")
sql.exec("INSERT INTO orders VALUES (42,'2026-10-17',NULL,'Алматы','Самовывоз','',20000,5000,15000,0,'not_sent','active')")
const expected=[42,'2026-10-17',0,'Алматы','Самовывоз','',20000,5000,15000,0,'not_sent','active']
assert.deepEqual(sql.prepare(match[1]).all(...expected),[],'Matching order snapshot must pass')
sql.exec('UPDATE orders SET received_amount=6000 WHERE id=42')
assert.throws(()=>sql.prepare(match[1]).all(...expected),/malformed JSON|JSON|ORDER_METADATA_STALE/,'A changed payment must fail closed')
sql.exec("UPDATE orders SET received_amount=5000,shipping_status='sent' WHERE id=42")
assert.throws(()=>sql.prepare(match[1]).all(...expected),/malformed JSON|JSON|ORDER_METADATA_STALE/,'Shipment concurrent with edit must fail closed')
sql.close()
console.log('SAFE_METADATA_ONLY_AFTER_EXCHANGE_AND_CAS_NO_STOCK_FINANCE_REWRITE_PASSED')
